<?= $this->section('main-content') ?>
<main class="dashboard-container" aria-labelledby="doctor-appointments-title"><div class="page-heading"><div><div class="page-eyebrow">Schedule / patient queue</div><h1 id="doctor-appointments-title">Appointments</h1><p class="text-muted mb-0">Create and manage appointments within your clinic scope.</p></div><div><a href="<?= base_url('doctor/clinical') ?>" class="btn btn-light mr-2">Today’s queue</a><button class="btn btn-primary" data-toggle="collapse" data-target="#new-doctor-appointment" aria-expanded="false">New appointment</button></div></div><div class="collapse mb-4" id="new-doctor-appointment"><div class="card"><div class="card-header"><h2 class="h5 mb-0">Schedule appointment</h2></div><form id="doctor-appointment-create-form"><div class="card-body row"><?= csrf_field() ?><div class="form-group col-md-6"><label for="appointment-patient">Patient</label><select id="appointment-patient" name="patient_id" class="form-control selectpicker" data-live-search="true" title="Search patient" required><?php foreach ($patients as $patient): ?><option value="<?= (int) $patient['id'] ?>"><?= esc(trim($patient['first_name'] . ' ' . $patient['last_name']) . ' · ' . $patient['registration_number']) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-3"><label for="appointment-date">Date</label><input id="appointment-date" name="appointment_date" type="text" class="form-control datepicker" placeholder="yyyy-mm-dd" autocomplete="off" required></div><div class="form-group col-md-3"><label for="appointment-time">Time</label><input id="appointment-time" name="appointment_time" type="time" class="form-control" required></div><div class="form-group col-md-4"><label for="appointment-type">Consultation type</label><select id="appointment-type" name="appointment_type" class="form-control" required><option value="in_person">In person</option><option value="video">Video</option><option value="phone">Telephone</option></select></div><div class="form-group col-md-8"><label for="appointment-reason">Reason for visit <span class="text-muted">(optional)</span></label><input id="appointment-reason" name="reason_for_visit" class="form-control" maxlength="500"></div></div><div class="card-footer text-right"><button class="btn btn-primary" type="submit">Create appointment</button></div></form></div></div><div class="card"><div class="card-header"><div class="d-flex flex-wrap align-items-center justify-content-between"><h2 class="h5 mb-2 mb-md-0">Appointment register</h2><label class="sr-only" for="doctor-appointment-search">Search appointments</label><input id="doctor-appointment-search" name="search" value="<?= esc($filters['search'] ?? '') ?>" class="form-control form-control-sm" type="search" placeholder="Search patient, number, or status"></div></div><div class="table-responsive"><table class="table mb-0" id="doctor-appointments-table"><thead><tr><th>Appointment</th><th>Patient</th><th>Date/time</th><th>Type</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach ($appointments as $appointment): ?><tr><td><strong><?= esc($appointment['appointment_number']) ?></strong></td><td><?= esc(trim(($appointment['patient_first_name'] ?? '') . ' ' . ($appointment['patient_last_name'] ?? ''))) ?><br><small class="text-muted"><?= esc($appointment['registration_number'] ?? '') ?></small></td><td><?= esc($appointment['appointment_date']) ?><br><small><?= esc(substr((string) $appointment['appointment_time'], 0, 5)) ?></small></td><td><?= esc(ucwords(str_replace('_', ' ', $appointment['appointment_type']))) ?></td><td><span class="badge badge-light"><?= esc(ucwords(str_replace('_', ' ', $appointment['status']))) ?></span></td><td class="text-right"><a class="btn btn-sm btn-outline-primary mr-1" href="<?= base_url('doctor/appointments/' . (int) $appointment['id']) ?>">Open</a><?php if (! in_array($appointment['status'], ['completed', 'cancelled', 'no_show'], true)): ?><button class="btn btn-sm btn-outline-secondary js-reschedule" data-id="<?= (int) $appointment['id'] ?>">Reschedule</button> <button class="btn btn-sm btn-outline-danger js-cancel" data-id="<?= (int) $appointment['id'] ?>">Cancel</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if ($appointments === []): ?><div class="empty-state"><i class="bi bi-calendar-x d-block h3 mb-2" aria-hidden="true"></i><div>No appointments found</div><small>Assigned appointments will appear here.</small></div><?php endif; ?></div><?= view(DOCTOR_VIEW . 'parts/pagination', ['pagination' => $pagination ?? [], 'filters' => $filters ?? []]) ?></main>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script>$(function(){$('.selectpicker').selectpicker();$('#doctor-appointment-create-form').on('submit',function(e){e.preventDefault();ajaxRequest({url:'<?= base_url('doctor/appointments/create') ?>',data:$(this).serialize(),success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);if(r.errors)bindFormError('#doctor-appointment-create-form',r.errors);}}});});$('.js-cancel').on('click',function(){const id=$(this).data('id');if(!confirm('Cancel this appointment?'))return;ajaxRequest({url:'<?= base_url('doctor/appointments/cancel') ?>/'+id,data:{cancellation_reason:'Cancelled by doctor'},success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else showError(r.msg);}});});$('.js-reschedule').on('click',function(){const id=$(this).data('id'),date=prompt('New date (YYYY-MM-DD):'),time=prompt('New time (HH:MM):');if(!date||!time)return;ajaxRequest({url:'<?= base_url('doctor/appointments/reschedule') ?>/'+id,data:{appointment_date:date,appointment_time:time},success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else showError(r.msg);}});});});</script><?= $this->endSection() ?>
